-- Mirrors the production-readiness marketplace operations migration applied to the connected project.
create table if not exists public.seller_business_profiles (seller_id uuid primary key references public.sellers(id) on delete cascade,legal_business_name text,business_type text,registration_number text,tax_id text,contact_name text,contact_phone text,contact_email text,address_line1 text,address_line2 text,city text,region text,country text not null default 'Ghana',verification_status text not null default 'pending' check(verification_status in('pending','verified','rejected')),created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table if not exists public.seller_bank_accounts (id uuid primary key default gen_random_uuid(),seller_id uuid not null references public.sellers(id) on delete cascade,bank_name text not null,account_name text not null,account_number_last4 text not null,payout_provider text,provider_recipient_code text,is_default boolean not null default false,verification_status text not null default 'pending' check(verification_status in('pending','verified','rejected')),created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table if not exists public.seller_documents (id uuid primary key default gen_random_uuid(),seller_id uuid not null references public.sellers(id) on delete cascade,document_type text not null,storage_path text not null,status text not null default 'pending' check(status in('pending','approved','rejected')),reviewed_by uuid references public.profiles(id),reviewed_at timestamptz,rejection_reason text,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table if not exists public.returns (id uuid primary key default gen_random_uuid(),order_id uuid not null references public.orders(id) on delete restrict,customer_id uuid not null references public.profiles(id) on delete restrict,status text not null default 'requested' check(status in('requested','approved','rejected','pickup_scheduled','received','inspected','refunded','cancelled')),reason_code text not null,reason text,customer_notes text,seller_notes text,admin_notes text,requested_at timestamptz not null default now(),approved_at timestamptz,received_at timestamptz,refunded_at timestamptz,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table if not exists public.return_items (id uuid primary key default gen_random_uuid(),return_id uuid not null references public.returns(id) on delete cascade,order_item_id uuid not null references public.order_items(id) on delete restrict,quantity integer not null check(quantity>0),condition text,resolution text check(resolution is null or resolution in('refund','replacement','store_credit')),created_at timestamptz not null default now(),unique(return_id,order_item_id));
create table if not exists public.refunds (id uuid primary key default gen_random_uuid(),order_id uuid not null references public.orders(id) on delete restrict,return_id uuid references public.returns(id) on delete set null,payment_id uuid references public.payments(id) on delete set null,amount numeric not null check(amount>=0),currency char(3) not null default 'GHS',method text not null default 'original_payment',status text not null default 'pending' check(status in('pending','processing','completed','failed','cancelled')),provider_reference text unique,reason text,processed_at timestamptz,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table if not exists public.seller_ledger_entries (id uuid primary key default gen_random_uuid(),seller_id uuid not null references public.sellers(id) on delete restrict,order_item_id uuid references public.order_items(id) on delete set null,payout_id uuid references public.seller_payouts(id) on delete set null,entry_type text not null check(entry_type in('sale','commission','refund','adjustment','payout','reversal')),amount numeric not null,currency char(3) not null default 'GHS',description text,reference text,created_at timestamptz not null default now());
create table if not exists public.seller_metrics_daily (id uuid primary key default gen_random_uuid(),seller_id uuid not null references public.sellers(id) on delete cascade,metric_date date not null,orders_count integer not null default 0,units_sold integer not null default 0,gross_sales numeric not null default 0,refunds numeric not null default 0,commission numeric not null default 0,rating_average numeric not null default 0,cancellation_rate numeric not null default 0,fulfillment_rate numeric not null default 0,created_at timestamptz not null default now(),updated_at timestamptz not null default now(),unique(seller_id,metric_date));
create table if not exists public.campaigns (id uuid primary key default gen_random_uuid(),name text not null,slug text unique not null,description text,campaign_type text not null default 'promotion' check(campaign_type in('promotion','flash_sale','seasonal','featured')),starts_at timestamptz not null,ends_at timestamptz not null,status text not null default 'draft' check(status in('draft','scheduled','active','paused','ended','cancelled')),discount_type text check(discount_type is null or discount_type in('percentage','fixed')),discount_value numeric check(discount_value is null or discount_value>0),max_discount_amount numeric,created_by uuid references public.profiles(id),created_at timestamptz not null default now(),updated_at timestamptz not null default now(),check(ends_at>starts_at));
create table if not exists public.campaign_products (campaign_id uuid not null references public.campaigns(id) on delete cascade,product_id uuid not null references public.products(id) on delete cascade,campaign_price numeric check(campaign_price is null or campaign_price>=0),stock_limit integer check(stock_limit is null or stock_limit>0),created_at timestamptz not null default now(),primary key(campaign_id,product_id));
create table if not exists public.coupon_redemptions (id uuid primary key default gen_random_uuid(),coupon_id uuid not null references public.coupons(id) on delete restrict,customer_id uuid not null references public.profiles(id) on delete restrict,order_id uuid not null unique references public.orders(id) on delete restrict,discount_amount numeric not null check(discount_amount>=0),created_at timestamptz not null default now(),unique(coupon_id,customer_id,order_id));
create table if not exists public.advertisements (id uuid primary key default gen_random_uuid(),seller_id uuid references public.sellers(id) on delete set null,name text not null,placement text not null check(placement in('home_hero','home_banner','category','search','product')),target_url text,image_url text,budget numeric not null default 0 check(budget>=0),spend numeric not null default 0 check(spend>=0),bid_amount numeric not null default 0 check(bid_amount>=0),starts_at timestamptz not null,ends_at timestamptz not null,status text not null default 'draft' check(status in('draft','pending','active','paused','ended','rejected')),impressions bigint not null default 0,clicks bigint not null default 0,created_at timestamptz not null default now(),updated_at timestamptz not null default now(),check(ends_at>starts_at));
create table if not exists public.ad_events (id uuid primary key default gen_random_uuid(),advertisement_id uuid not null references public.advertisements(id) on delete cascade,event_type text not null check(event_type in('impression','click','conversion')),customer_id uuid references public.profiles(id) on delete set null,created_at timestamptz not null default now());
create table if not exists public.delivery_zones (id uuid primary key default gen_random_uuid(),name text not null,region text,city text,postal_prefix text,is_active boolean not null default true,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table if not exists public.shipping_rates (id uuid primary key default gen_random_uuid(),zone_id uuid not null references public.delivery_zones(id) on delete cascade,method text not null,min_weight_grams integer not null default 0,max_weight_grams integer,price numeric not null check(price>=0),eta_min_days integer,eta_max_days integer,is_active boolean not null default true,created_at timestamptz not null default now(),check(max_weight_grams is null or max_weight_grams>=min_weight_grams));
create table if not exists public.pickup_stations (id uuid primary key default gen_random_uuid(),name text not null,code text unique not null,address text not null,city text not null,region text not null,phone text,opening_hours jsonb not null default '{}',is_active boolean not null default true,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table if not exists public.shipment_events (id uuid primary key default gen_random_uuid(),shipment_id uuid not null references public.shipments(id) on delete cascade,status text not null,location text,description text,event_at timestamptz not null default now(),created_at timestamptz not null default now());
create table if not exists public.warehouses (id uuid primary key default gen_random_uuid(),seller_id uuid references public.sellers(id) on delete cascade,name text not null,address_line1 text not null,city text not null,region text not null,country text not null default 'Ghana',is_active boolean not null default true,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table if not exists public.warehouse_inventory (id uuid primary key default gen_random_uuid(),warehouse_id uuid not null references public.warehouses(id) on delete cascade,product_id uuid not null references public.products(id) on delete cascade,variant_id uuid references public.product_variants(id) on delete cascade,quantity integer not null default 0 check(quantity>=0),reserved_quantity integer not null default 0 check(reserved_quantity>=0),updated_at timestamptz not null default now(),unique(warehouse_id,product_id,variant_id));
create table if not exists public.support_tickets (id uuid primary key default gen_random_uuid(),customer_id uuid references public.profiles(id) on delete set null,seller_id uuid references public.sellers(id) on delete set null,subject text not null,category text not null default 'general',priority text not null default 'normal' check(priority in('low','normal','high','urgent')),status text not null default 'open' check(status in('open','pending','resolved','closed')),order_id uuid references public.orders(id) on delete set null,assigned_to uuid references public.profiles(id),created_at timestamptz not null default now(),updated_at timestamptz not null default now(),resolved_at timestamptz);
create table if not exists public.support_messages (id uuid primary key default gen_random_uuid(),ticket_id uuid not null references public.support_tickets(id) on delete cascade,sender_id uuid references public.profiles(id) on delete set null,message text not null,internal_note boolean not null default false,created_at timestamptz not null default now());
create or replace function public.get_product_available_quantity(p_product_id uuid,p_variant_id uuid default null) returns integer language sql stable security definer set search_path=public,pg_temp as $$ select greatest(0,coalesce(case when p_variant_id is null then (select quantity-reserved_quantity from public.inventory where product_id=p_product_id) else (select quantity-reserved_quantity from public.variant_inventory where variant_id=p_variant_id) end,0)); $$;
revoke all on function public.get_product_available_quantity(uuid,uuid) from public;grant execute on function public.get_product_available_quantity(uuid,uuid) to anon,authenticated;
create or replace function public.request_order_return(p_order_id uuid,p_reason_code text,p_reason text default null) returns jsonb language plpgsql security definer set search_path=public,pg_temp as $$ declare v_user uuid:=auth.uid();v_status order_status;v_return uuid;begin if v_user is null then raise exception 'Not authenticated';end if;select status into v_status from public.orders where id=p_order_id and customer_id=v_user for update;if v_status is null then raise exception 'Order not found';end if;if v_status<>'delivered' then raise exception 'Only delivered orders can be returned';end if;if exists(select 1 from public.returns where order_id=p_order_id and status not in('rejected','cancelled')) then raise exception 'A return request already exists';end if;insert into public.returns(order_id,customer_id,reason_code,reason) values(p_order_id,v_user,trim(p_reason_code),nullif(trim(p_reason),'')) returning id into v_return;insert into public.notifications(user_id,title,message,type,data) values(v_user,'Return request received','Your return request is awaiting review.','return_requested',jsonb_build_object('return_id',v_return,'order_id',p_order_id));return jsonb_build_object('success',true,'return_id',v_return);end$$;
revoke all on function public.request_order_return(uuid,text,text) from public;grant execute on function public.request_order_return(uuid,text,text) to authenticated;
create or replace function public.validate_coupon(p_code text,p_order_amount numeric) returns jsonb language plpgsql stable security definer set search_path=public,pg_temp as $$ declare c public.coupons%rowtype;v_discount numeric;begin select * into c from public.coupons where code=trim(p_code) and is_active and (starts_at is null or starts_at<=now()) and (expires_at is null or expires_at>=now()) for share;if c.id is null then return jsonb_build_object('valid',false,'error','Invalid or expired coupon');end if;if p_order_amount<coalesce(c.minimum_order_amount,0) then return jsonb_build_object('valid',false,'error','Minimum order amount not met');end if;if c.usage_limit is not null and c.used_count>=c.usage_limit then return jsonb_build_object('valid',false,'error','Coupon usage limit reached');end if;v_discount:=case when c.discount_type='percentage' then least(p_order_amount*c.discount_value/100,coalesce(c.maximum_discount_amount,p_order_amount)) else least(c.discount_value,p_order_amount) end;return jsonb_build_object('valid',true,'coupon_id',c.id,'code',c.code,'discount_amount',round(v_discount,2));end$$;
revoke all on function public.validate_coupon(text,numeric) from public;grant execute on function public.validate_coupon(text,numeric) to anon,authenticated;
create index if not exists idx_returns_customer on public.returns(customer_id,created_at desc);create index if not exists idx_returns_order on public.returns(order_id);create index if not exists idx_refunds_order on public.refunds(order_id,created_at desc);create index if not exists idx_ledger_seller on public.seller_ledger_entries(seller_id,created_at desc);create index if not exists idx_metrics_seller_date on public.seller_metrics_daily(seller_id,metric_date desc);create index if not exists idx_campaign_products_product on public.campaign_products(product_id);create index if not exists idx_ads_status_window on public.advertisements(status,starts_at,ends_at);create index if not exists idx_ad_events_ad on public.ad_events(advertisement_id,created_at desc);create index if not exists idx_shipment_events_shipment on public.shipment_events(shipment_id,event_at desc);create index if not exists idx_warehouse_inventory_product on public.warehouse_inventory(product_id,variant_id);create index if not exists idx_support_customer on public.support_tickets(customer_id,created_at desc);create index if not exists idx_support_seller on public.support_tickets(seller_id,created_at desc);create index if not exists idx_support_status on public.support_tickets(status,priority,updated_at desc);
-- RLS policies intentionally mirror ownership boundaries; admin uses private.is_admin().
alter table public.seller_business_profiles enable row level security;alter table public.seller_bank_accounts enable row level security;alter table public.seller_documents enable row level security;alter table public.returns enable row level security;alter table public.return_items enable row level security;alter table public.refunds enable row level security;alter table public.seller_ledger_entries enable row level security;alter table public.seller_metrics_daily enable row level security;alter table public.campaigns enable row level security;alter table public.campaign_products enable row level security;alter table public.coupon_redemptions enable row level security;alter table public.advertisements enable row level security;alter table public.ad_events enable row level security;alter table public.delivery_zones enable row level security;alter table public.shipping_rates enable row level security;alter table public.pickup_stations enable row level security;alter table public.shipment_events enable row level security;alter table public.warehouses enable row level security;alter table public.warehouse_inventory enable row level security;alter table public.support_tickets enable row level security;alter table public.support_messages enable row level security;
create policy seller_business_owner on public.seller_business_profiles for all to authenticated using(exists(select 1 from public.sellers s where s.id=seller_id and s.owner_id=auth.uid())) with check(exists(select 1 from public.sellers s where s.id=seller_id and s.owner_id=auth.uid()));create policy seller_business_admin on public.seller_business_profiles for all to authenticated using(private.is_admin()) with check(private.is_admin());
create policy seller_bank_owner on public.seller_bank_accounts for all to authenticated using(exists(select 1 from public.sellers s where s.id=seller_id and s.owner_id=auth.uid())) with check(exists(select 1 from public.sellers s where s.id=seller_id and s.owner_id=auth.uid()));create policy seller_bank_admin on public.seller_bank_accounts for all to authenticated using(private.is_admin()) with check(private.is_admin());
create policy seller_docs_owner on public.seller_documents for all to authenticated using(exists(select 1 from public.sellers s where s.id=seller_id and s.owner_id=auth.uid())) with check(exists(select 1 from public.sellers s where s.id=seller_id and s.owner_id=auth.uid()));create policy seller_docs_admin on public.seller_documents for all to authenticated using(private.is_admin()) with check(private.is_admin());
create policy returns_customer on public.returns for select to authenticated using(customer_id=auth.uid());create policy returns_seller on public.returns for select to authenticated using(exists(select 1 from public.order_items oi join public.sellers s on s.id=oi.seller_id where oi.order_id=returns.order_id and s.owner_id=auth.uid()));create policy returns_admin on public.returns for all to authenticated using(private.is_admin()) with check(private.is_admin());
create policy return_items_customer on public.return_items for select to authenticated using(exists(select 1 from public.returns r where r.id=return_id and r.customer_id=auth.uid()));create policy return_items_seller on public.return_items for select to authenticated using(exists(select 1 from public.returns r join public.order_items oi on oi.order_id=r.order_id join public.sellers s on s.id=oi.seller_id where r.id=return_id and s.owner_id=auth.uid()));create policy return_items_admin on public.return_items for all to authenticated using(private.is_admin()) with check(private.is_admin());
create policy refunds_customer on public.refunds for select to authenticated using(exists(select 1 from public.orders o where o.id=order_id and o.customer_id=auth.uid()));create policy refunds_admin on public.refunds for all to authenticated using(private.is_admin()) with check(private.is_admin());
create policy ledger_seller on public.seller_ledger_entries for select to authenticated using(exists(select 1 from public.sellers s where s.id=seller_id and s.owner_id=auth.uid()));create policy ledger_admin on public.seller_ledger_entries for all to authenticated using(private.is_admin()) with check(private.is_admin());create policy metrics_seller on public.seller_metrics_daily for select to authenticated using(exists(select 1 from public.sellers s where s.id=seller_id and s.owner_id=auth.uid()));create policy metrics_admin on public.seller_metrics_daily for all to authenticated using(private.is_admin()) with check(private.is_admin());
create policy campaigns_public on public.campaigns for select to anon,authenticated using(status in('scheduled','active') and starts_at<=now() and ends_at>now());create policy campaigns_admin on public.campaigns for all to authenticated using(private.is_admin()) with check(private.is_admin());create policy campaign_products_public on public.campaign_products for select to anon,authenticated using(exists(select 1 from public.campaigns c where c.id=campaign_id and c.status in('scheduled','active') and c.starts_at<=now() and c.ends_at>now()));create policy campaign_products_admin on public.campaign_products for all to authenticated using(private.is_admin()) with check(private.is_admin());
create policy coupon_redemptions_customer on public.coupon_redemptions for select to authenticated using(customer_id=auth.uid());create policy coupon_redemptions_admin on public.coupon_redemptions for all to authenticated using(private.is_admin()) with check(private.is_admin());
create policy ads_public on public.advertisements for select to anon,authenticated using(status='active' and starts_at<=now() and ends_at>now());create policy ads_seller on public.advertisements for all to authenticated using(exists(select 1 from public.sellers s where s.id=seller_id and s.owner_id=auth.uid())) with check(exists(select 1 from public.sellers s where s.id=seller_id and s.owner_id=auth.uid()));create policy ads_admin on public.advertisements for all to authenticated using(private.is_admin()) with check(private.is_admin());create policy ad_events_customer_insert on public.ad_events for insert to authenticated with check(customer_id=auth.uid());create policy ad_events_admin on public.ad_events for all to authenticated using(private.is_admin()) with check(private.is_admin());
create policy delivery_zones_public on public.delivery_zones for select to anon,authenticated using(is_active);create policy delivery_zones_admin on public.delivery_zones for all to authenticated using(private.is_admin()) with check(private.is_admin());create policy shipping_rates_public on public.shipping_rates for select to anon,authenticated using(is_active);create policy shipping_rates_admin on public.shipping_rates for all to authenticated using(private.is_admin()) with check(private.is_admin());create policy pickup_public on public.pickup_stations for select to anon,authenticated using(is_active);create policy pickup_admin on public.pickup_stations for all to authenticated using(private.is_admin()) with check(private.is_admin());
