create policy warehouses_seller on public.warehouses for all to authenticated using(exists(select 1 from public.sellers s where s.id=seller_id and s.owner_id=auth.uid())) with check(exists(select 1 from public.sellers s where s.id=seller_id and s.owner_id=auth.uid()));create policy warehouses_admin on public.warehouses for all to authenticated using(private.is_admin()) with check(private.is_admin());create policy warehouse_inventory_seller on public.warehouse_inventory for all to authenticated using(exists(select 1 from public.warehouses w join public.sellers s on s.id=w.seller_id where w.id=warehouse_id and s.owner_id=auth.uid())) with check(exists(select 1 from public.warehouses w join public.sellers s on s.id=w.seller_id where w.id=warehouse_id and s.owner_id=auth.uid()));create policy warehouse_inventory_admin on public.warehouse_inventory for all to authenticated using(private.is_admin()) with check(private.is_admin());
create policy support_customer on public.support_tickets for select to authenticated using(customer_id=auth.uid());create policy support_seller on public.support_tickets for select to authenticated using(exists(select 1 from public.sellers s where s.id=seller_id and s.owner_id=auth.uid()));create policy support_admin on public.support_tickets for all to authenticated using(private.is_admin()) with check(private.is_admin());create policy support_messages_customer on public.support_messages for select to authenticated using(exists(select 1 from public.support_tickets t where t.id=ticket_id and t.customer_id=auth.uid()));create policy support_messages_seller on public.support_messages for select to authenticated using(exists(select 1 from public.support_tickets t join public.sellers s on s.id=t.seller_id where t.id=ticket_id and s.owner_id=auth.uid()));create policy support_messages_admin on public.support_messages for all to authenticated using(private.is_admin()) with check(private.is_admin());
-- Existing privileged RPCs are only callable by authenticated users; each function enforces its own authorization.
revoke all on function public.admin_set_seller_status(uuid,text) from public;grant execute on function public.admin_set_seller_status(uuid,text) to authenticated;revoke all on function public.admin_set_order_status(uuid,text) from public;grant execute on function public.admin_set_order_status(uuid,text) to authenticated;revoke all on function public.submit_product_review(uuid,uuid,integer,text,text) from public;grant execute on function public.submit_product_review(uuid,uuid,integer,text,text) to authenticated;revoke all on function public.cancel_order(uuid) from public;grant execute on function public.cancel_order(uuid) to authenticated;revoke all on function public.create_order(uuid,text,text) from public;grant execute on function public.create_order(uuid,text,text) to authenticated;revoke all on function public.seller_set_order_status(uuid,text) from public;grant execute on function public.seller_set_order_status(uuid,text) to authenticated;